from jsonb_to_recordset('[{"id": "hankook-634046", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.634046.html", "title": "한국타이어, 폭스바겐 ‘ID.폴로·ID.크로스’에 아이온 공급해 EV 파트너십 강화", "category": "공급 / 계약", "date": "2026-10-21", "topics": ["전기차 / 저회전저항", "겨울용 / 올웨더", "타이어 설계 / 성능"], "tags": ["아이온 에보", "아이온 아이셉트", "V자형 트레드", "전용 컴파운드"], "summary": "폭스바겐 소형 전기차용 아이온의 여름·겨울 설계를 설명한다. 겨울용 제품은 V자형 패턴과 전용 고무 배합으로 눈길 구동·제동에 대응한다.", "study": "공부 질문: 전기차의 하중·순간 토크 요구와 겨울철 접지 요구를 패턴과 재료 설계로 어떻게 함께 만족시킬까?"}, {"id": "hankook-634039", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.634039.html", "title": "한국타이어, 대형 카고 후륜용 타이어 ‘스마트플렉스 DH51’ 신규 규격 출시", "category": "상용차 / 내구성", "date": "2026-10-19", "topics": ["타이어 설계 / 성능", "소음 / 진동"], "tags": ["스마트플렉스 DH51", "3D 사이프", "히든 그루브", "비드 구조"], "summary": "대형 카고 후륜 타이어의 새 규격과 설계 요소를 소개한다. 3D 사이프, 마모 후 드러나는 홈, 비드 보강을 통해 수명·빗길 성능·내구성을 함께 고려한다.", "study": "공부 질문: 구동축 타이어에서 견인력, 균일 마모, 소음과 비드 내구성의 설계 우선순위는 어떻게 달라질까?"}, {"id": "hankook-633936", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633936.html", "title": "한국타이어, ‘2026 IDEA 디자인 어워드’ 본상 2관왕", "category": "미래 모빌리티 / 비공기입", "date": "2026-09-30", "topics": ["공정 / 자원순환", "컴파운드 / 재료"], "tags": ["휠봇2", "3축 구동", "블래더", "업사이클링"], "summary": "구형 바퀴를 이용하는 휠봇2와 생산 부산물인 블래더를 재활용한 디자인 사례를 다룬다. 휠봇2의 전 방향 이동과 블래더 분말의 제품화가 구체적인 기술 주제다.", "study": "공부 질문: 구형 휠의 구동·조향 자유도와 생산 부산물의 물성·가공성을 각각 어떤 시험으로 확인해야 할까?"}, {"id": "hankook-633925", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633925.html", "title": "한국타이어, 미국 ‘레이싱 아메리카’에 레이싱 타이어 독점 공급 및 후원", "category": "공급 / 계약", "date": "2026-09-29", "topics": [], "tags": ["레이싱 아메리카", "2027~2031", "기술 지원", "레이싱 타이어"], "summary": "레이싱 아메리카 주요 네 대회에 2027년부터 2031년까지 타이어와 기술 지원을 제공하는 계약을 소개한다. 신규 공급과 기존 파트너십 갱신을 함께 다룬다.", "study": "공부 질문: 여러 대회에 동일 공급사가 참여할 때 규격·수요 예측·현장 기술 지원·품질 대응 범위를 계약에서 어떻게 정할까?"}, {"id": "hankook-633919", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633919.html", "title": "한국타이어, 폭스바겐 ‘아틀라스’ OE 공급…북미 SUV 포트폴리오 확대", "category": "공급 / 계약", "date": "2026-09-28", "topics": ["타이어 설계 / 성능", "소음 / 진동", "컴파운드 / 재료"], "tags": ["다이나프로 HPX", "3D 그립컨트롤 사이프", "널링", "멀티 피치"], "summary": "아틀라스용 타이어의 맞물림 사이프와 넓은 접지면 설계를 설명한다. 고무 배합은 마모 성능에, 홈 내부 널링과 피치 배열은 소음 저감에 연결된다.", "study": "공부 질문: 블록의 움직임을 억제하면서 접지력을 유지하는 방법과 피치 배열이 소음을 바꾸는 원리를 정리해보자."}, {"id": "hankook-633895", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633895.html", "title": "한국타이어, 유럽 트레일러 제조사 ‘슈미츠 카고불’과 OE 파트너십 체결", "category": "공급 / 계약", "date": "2026-09-18", "topics": ["상용차 / 내구성"], "tags": ["슈미츠 카고불", "상용차 OE", "공급 연장", "스마텍"], "summary": "슈미츠 카고불과 상용 타이어 공급을 2030년 6월까지 연장한 계약이다. 사용 목적이 다른 상용 타이어 제품과 품질·수명 요구를 함께 소개한다.", "study": "공부 질문: 장기 공급에서 고객 승인 규격, 설계 변경, 생산 거점과 공급 중단 위험을 어떻게 관리할까?"}, {"id": "hankook-633892", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633892.html", "title": "한국타이어, ‘벨기에 랠리 챔피언십’ 공식 타이어 공급사 선정", "category": "공급 / 계약", "date": "2026-09-17", "topics": [], "tags": ["BRC", "2027~2029", "랠리 타이어", "독점 공급"], "summary": "벨기에 랠리 챔피언십의 세 클래스에 2027년부터 2029년까지 레이싱 타이어를 공급하는 계약을 소개한다.", "study": "공부 질문: 대회별 사용 규정과 타이어 규격, 현장 재고·교체 수요를 공급 계획에 어떻게 반영할까?"}, {"id": "hankook-633874", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633874.html", "title": "한국타이어, 현대 ‘아반떼’ 신차용 타이어 공급으로 전략적 파트너십 강화", "category": "공급 / 계약", "date": "2026-09-15", "topics": ["타이어 설계 / 성능", "소음 / 진동", "겨울용 / 올웨더"], "tags": ["키너지 XP", "프로파일", "숄더 그루브", "피치 시퀀싱"], "summary": "아반떼용 키너지 XP의 사계절 접지·마모·정숙성 설계를 소개한다. 고무 배합과 프로파일, 사이프·숄더 홈, 널링·피치 배열의 역할을 구분할 수 있다.", "study": "공부 질문: 눈길 성능을 위한 홈 설계와 정숙성·균일 마모를 위한 형상 설계는 어떤 상충 관계가 있을까?"}, {"id": "hankook-633829", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633829.html", "title": "한국타이어, 금산공장에 자가소비형 태양광 발전설비 신규 구축", "category": "환경 / 에너지", "date": "2026-09-03", "topics": ["공정 / 자원순환"], "tags": ["금산공장", "자가소비형 태양광", "5069kW", "공장 전력"], "summary": "금산공장의 원자재·완제품 창고 지붕에 합계 5,069kW 태양광 설비를 설치했다. 발전 전력의 공장 내 사용과 이에 따른 배출량 저감의 기대 효과를 설명한다.", "study": "공부 질문: 공장 부하 곡선과 태양광 발전 시간대가 다를 때 자가소비율·전력 품질·설비 운영을 어떻게 검토할까?"}, {"id": "hankook-633821", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633821.html", "title": "한국타이어, 겨울용 퍼포먼스 타이어 신제품 ‘윈터 아이셉트 에보4’ 국내 출시", "category": "겨울용 / 올웨더", "date": "2026-09-01", "topics": ["타이어 설계 / 성능", "컴파운드 / 재료"], "tags": ["윈터 아이셉트 에보4", "횡 방향 그루브", "다각도 사이프", "마일리지"], "summary": "겨울용 에보4의 넓은 횡 방향 홈과 다각도 사이프를 설명한다. 눈길 접지·견인, 배수와 마모 수명을 함께 개선하려는 설계 사례다.", "study": "공부 질문: 사이프의 방향·밀도와 블록 강성 변화가 눈길 견인력, 젖은 노면 제동과 마모에 어떻게 연결될까?"}, {"id": "hankook-633802", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633802.html", "title": "한국타이어, ‘2026 레드닷 디자인 어워드’ 디자인 콘셉트 부문 6관왕", "category": "미래 모빌리티 / 비공기입", "date": "2026-08-26", "topics": ["컴파운드 / 재료"], "tags": ["아이플렉스 Gen 2", "비공기입 타이어", "메디 버디", "지속가능 콘셉트"], "summary": "비공기입 타이어 아이플렉스 Gen 2와 이동형 AI 링거 등 미래 디자인 결과물을 소개한다. 연구 콘셉트의 적용 분야와 실제 양산 제품을 구분해서 읽을 자료다.", "study": "공부 질문: 콘셉트의 기능 시연에서 양산 검증으로 넘어가려면 하중·내구·제어·사용 환경 요구사항을 어떻게 구체화해야 할까?"}, {"id": "hankook-633796", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633796.html", "title": "한국타이어, ‘폴스타 4’에 ‘아이온’ 공급... 프리미엄 전기차 파트너십 확대", "category": "공급 / 계약", "date": "2026-08-25", "topics": ["전기차 / 저회전저항"], "tags": ["폴스타 4", "아이온 에보 SUV", "EV 요구 성능"], "summary": "폴스타 4에 아이온 에보 SUV를 공급하는 첫 협력을 소개한다. 차종에 맞춘 규격과 전기차용 타이어의 소음·수명·접지·회전저항 요구를 다룬다.", "study": "공부 질문: 신규 고객과의 개발에서 요구 성능 합의, 규격 승인, 품질 검증과 양산 일정을 어떻게 연결할까?"}, {"id": "hankook-633728", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633728.html", "title": "한국타이어, 쿠프라 ‘라발’에 ‘아이온’ 공급... 전동화 라인업 파트너십 강화", "category": "공급 / 계약", "date": "2026-08-13", "topics": ["전기차 / 저회전저항", "컴파운드 / 재료", "타이어 설계 / 성능"], "tags": ["아이온 에보", "아라미드 보강 벨트", "EV 형상", "이상 마모"], "summary": "쿠프라 라발용 아이온 에보의 형상과 아라미드 보강 벨트를 설명한다. 전기차의 하중·토크에 대응하면서 코너링 강성, 회전저항과 마모를 함께 고려한다.", "study": "공부 질문: 보강 벨트와 프로파일 변경을 평가할 때 강성·전비·소음·수명의 비교 조건을 어떻게 맞춰야 할까?"}, {"id": "hankook-633710", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633710.html", "title": "한국타이어, 2026년 2분기 실적 발표", "category": "재무 / 사업전략", "date": "2026-08-11", "topics": [], "tags": ["2026년 2분기", "연결 실적", "타이어 부문", "제품 믹스"], "summary": "2026년 2분기 연결 실적과 타이어 사업 실적을 구분해 발표했다. 타이어 부문의 매출·이익 변화와 고인치·전기차 제품 구성, 생산능력 강화가 주요 내용이다.", "study": "공부 질문: 연결 범위 변화와 타이어 자체 성장 효과를 구분하고 제품 구성·원가·생산능력이 수익성에 미치는 영향을 정리해보자."}, {"id": "hankook-633703", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633703.html", "title": "한국타이어, BMW i7에 ''아이온'' 공급하며 전동화 파트너십 강화", "category": "공급 / 계약", "date": "2026-08-06", "topics": ["전기차 / 저회전저항", "품질 / 생산관리"], "tags": ["BMW i7", "스타 인증", "아이온", "차종별 승인"], "summary": "BMW i7용 아이온 세 제품과 BMW의 스타 인증을 소개한다. 사계절·겨울·퍼포먼스 제품을 차종 요구에 맞춰 개발·승인하는 사례다.", "study": "공부 질문: 일반 교체용 규격 적합성과 완성차 전용 인증의 차이를 정리하고 고객 승인 시험의 목적을 생각해보자."}, {"id": "hankook-633698", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633698.html", "title": "한국타이어, “기록적인 폭염” 여름철 올바른 타이어 관리 요령 제안", "category": "품질 / 생산관리", "date": "2026-08-05", "topics": ["타이어 설계 / 성능"], "tags": ["폭염", "공기압", "노면 온도", "타이어 점검"], "summary": "폭염과 장거리 주행 상황에서 타이어의 열·공기압·마모 상태를 점검할 필요성을 설명한다. 고온 노면에서의 사용 조건을 이해하기 위한 자료다.", "study": "공부 질문: 냉간 기준 공기압과 주행 중 온도 상승을 구분하고, 현장 고장 분석에 필요한 운행·하중·점검 기록을 정리해보자."}, {"id": "hankook-633631", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633631.html", "title": "한국타이어, 포르쉐 ‘911 카레라’에 신차용 타이어 공급", "category": "공급 / 계약", "date": "2026-07-27", "topics": ["타이어 설계 / 성능", "시험 / 성능검증", "컴파운드 / 재료"], "tags": ["911 카레라", "전후륜 프로파일", "전용 컴파운드", "NA2"], "summary": "후방 엔진 스포츠카의 전후륜 하중과 거동에 맞춘 타이어 개발 사례다. 앞뒤 규격·패턴·프로파일과 배합을 달리하고 여러 시험장에서 조향·고속·젖은 노면 성능을 검증했다.", "study": "공부 질문: 같은 차량의 전후륜 요구 성능이 다른 이유와 시험장별 평가 항목을 개발 요구사항에 연결해보자."}, {"id": "hankook-633599", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633599.html", "title": "한국타이어, 현대로템 무인소방로봇에 비공기입 타이어 ‘아이플렉스’ 공급", "category": "공급 / 계약", "date": "2026-07-21", "topics": ["미래 모빌리티 / 비공기입", "타이어 설계 / 성능", "시험 / 성능검증"], "tags": ["아이플렉스", "무인소방로봇", "이중 아치", "고하중"], "summary": "현대로템 무인소방로봇에 적용한 비공기입 타이어를 설명한다. 이중 아치 구조로 하중을 분산하고 화재 현장의 고하중·험로 조건에 대응하도록 공동 개발했다.", "study": "공부 질문: 공기압 없이 하중을 지지하는 구조의 강성·피로·접지 성능을 어떻게 검증하고 실제 임무 조건과 연결할까?"}, {"id": "hankook-633545", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633545.html", "title": "한국타이어, 전기차 올웨더 타이어 ‘아이온 플렉스 클라이밋’ 국내 출시", "category": "전기차 / 저회전저항", "date": "2026-07-13", "topics": ["겨울용 / 올웨더", "타이어 설계 / 성능"], "tags": ["아이온 플렉스 클라이밋", "올웨더", "전비", "그립"], "summary": "전기차용 올웨더 아이온 플렉스 클라이밋의 국내 출시와 적용 기술을 다룬다. 계절 대응 성능에 전기차의 정숙성·전비 요구를 함께 반영한 제품이다.", "study": "공부 질문: 올시즌·올웨더·겨울용의 목표 사용 조건을 구분하고, 전비와 저온 접지력을 동시에 평가할 기준을 정리해보자."}, {"id": "hankook-633536", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633536.html", "title": "한국타이어, 지속가능한 성장 전략 담은 ‘2025/26 ESG 보고서’ 발간", "category": "환경 / 에너지", "date": "2026-07-08", "topics": ["재무 / 사업전략", "구매 / 공급망"], "tags": ["ESG 보고서", "글로벌 규제", "지속가능 원료", "지배구조"], "summary": "2025/26 ESG 보고서의 환경·규제 대응과 지배구조 내용을 소개한다. 지속가능 원료 확대, 그룹 차원의 대응 체계와 주주환원 정책을 다룬다.", "study": "공부 질문: 원료·생산·사업 보고의 지표가 연결되는 경로를 그리고 목표·실적·외부 검증을 구분해 읽어보자."}, {"id": "hankook-633533", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633533.html", "title": "한국타이어, 독일 ‘아우토 빌트’ 전기차 전용 타이어 테스트 1위", "category": "시험 / 성능검증", "date": "2026-07-07", "topics": ["전기차 / 저회전저항", "겨울용 / 올웨더"], "tags": ["아우토 빌트", "아이온 플렉스 클라이밋", "젖은 노면", "마일리지"], "summary": "아이온 플렉스 클라이밋의 전문지 비교 시험 결과를 소개한다. 젖은·마른 노면과 수명 등 여러 항목을 함께 평가한 점을 살펴볼 수 있다.", "study": "공부 질문: 종합 순위만 보지 않고 시험 규격·노면·평가 가중치와 항목별 결과를 함께 확인해야 하는 이유는 무엇일까?"}, {"id": "hankook-633503", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633503.html", "title": "한국타이어, 준대형 카고 전륜용 타이어 ‘AH30+’ 신규 규격 출시", "category": "상용차 / 내구성", "date": "2026-07-02", "topics": ["타이어 설계 / 성능", "컴파운드 / 재료"], "tags": ["AH30+", "비드 컴파운드", "광폭 트레드", "숄더 러그"], "summary": "준대형 카고 전륜용 AH30+의 규격 확장과 설계를 설명한다. 접지 폭·비드 배합·홈과 숄더 패턴으로 내구성, 조향과 균일 마모를 고려한다.", "study": "공부 질문: 전륜의 조향 요구와 비드 내구 요구를 구분하고 하중·공기압·마모 형태를 설계 평가에 연결해보자."}, {"id": "hankook-633499", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633499.html", "title": "한국타이어, 소형화물트럭 및 밴 전용 타이어 ‘밴트라 트랜짓’ 국내 출시", "category": "상용차 / 내구성", "date": "2026-07-01", "topics": ["시험 / 성능검증", "타이어 설계 / 성능"], "tags": ["밴트라 트랜짓", "강화 벨트", "3D 커프", "테크노링"], "summary": "소형화물차·밴용 타이어의 강화 벨트와 3D 커프 구조를 소개한다. 테크노링에서 가혹 노면 내마모성을 확인한 개발 사례다.", "study": "공부 질문: 상용 밴의 반복 고하중을 시험 조건으로 바꾸고, 벨트 구조·마모·핸들링 결과를 어떻게 비교할까?"}, {"id": "hankook-633419", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633419.html", "title": "한국타이어, 장마철 안전운전 위한 올바른 타이어 관리 요령 제안", "category": "품질 / 생산관리", "date": "2026-06-16", "topics": ["타이어 설계 / 성능"], "tags": ["수막현상", "배수", "마모", "공기압"], "summary": "장마철 마모·공기압·손상 상태와 젖은 노면 안전의 관계를 설명한다. 배수가 원활하지 않을 때의 수막현상과 타이어 점검 항목을 다룬다.", "study": "공부 질문: 홈 깊이·속도·수막 조건이 달라질 때 제동 시험을 어떻게 비교하고, 사용 중 마모와 초기 설계를 어떻게 연결할까?"}, {"id": "hankook-633370", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633370.html", "title": "한국타이어, ‘지속가능 소재 적용 타이어 제조 기술 개발’ 킥오프 개최", "category": "공정 / 자원순환", "date": "2026-06-05", "topics": ["컴파운드 / 재료", "구매 / 공급망", "환경 / 에너지"], "tags": ["Tire-to-Tire", "폐타이어", "지속가능 소재", "성능 실증"], "summary": "폐타이어에서 원료를 회수하고 다시 타이어로 제품화하는 국가 연구과제를 소개한다. 순환 원료 확보, 제조 기술과 성능 실증을 산학연 협력으로 추진한다.", "study": "공부 질문: 회수 원료의 편차를 어떤 입고·배합·공정·제품 시험으로 관리할까? 개발 목표와 이미 달성한 실적도 구분해보자."}, {"id": "hankook-633307", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633307.html", "title": "한국타이어, 호주 내구레이스 시리즈 ‘APCES’ 공식 타이어 공급사 선정", "category": "공급 / 계약", "date": "2026-05-27", "topics": ["타이어 설계 / 성능", "컴파운드 / 재료"], "tags": ["APCES", "벤투스 TD Z221", "내구 레이스", "내열"], "summary": "호주 APCES의 2026~27 시즌에 벤투스 TD를 공급한다. 내구 레이스용 트레드와 고무 배합의 접지·핸들링·내열 성능을 함께 설명한다.", "study": "공부 질문: 짧은 최고 성능과 장시간 성능 유지 중 무엇을 어떻게 측정하고 공급 규격에 반영할까?"}, {"id": "hankook-633304", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633304.html", "title": "한국타이어, 혼다 최고 권위 품질상 ‘2025 우수 공급업체’ 수상", "category": "품질 / 생산관리", "date": "2026-05-27", "topics": ["구매 / 공급망", "공정 / 자원순환"], "tags": ["혼다", "품질 및 납기", "공급업체 평가", "생산 일관성"], "summary": "혼다 북미 공급업체 평가의 품질·납기 부문 수상을 다룬다. 생산 거점의 품질 일관성과 안정적인 공급·납기 관리가 평가된 사례다.", "study": "공부 질문: 고객 품질 지표와 납기 준수율을 생산 관리 지표로 어떻게 연결하고, 여러 공장의 편차를 어떻게 줄일까?"}, {"id": "hankook-633286", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633286.html", "title": "한국타이어 중국 가흥공장, 친환경 국제인증 ‘ISCC PLUS’ 획득", "category": "공정 / 자원순환", "date": "2026-05-22", "topics": ["환경 / 에너지", "구매 / 공급망"], "tags": ["가흥공장", "ISCC PLUS", "원료 추적", "인증"], "summary": "가흥공장이 지속가능 원료와 공급망을 대상으로 ISCC PLUS 인증을 받았다. 원료 수급부터 제조와 완제품까지 인증 범위를 관리하는 사례다.", "study": "공부 질문: 원료 추적성과 공정 기록을 어떤 방식으로 연결해야 인증된 원료의 투입·생산·출하 내역을 설명할 수 있을까?"}, {"id": "hankook-633279", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633279.html", "title": "한국타이어, 아우디 플래그십 SUV ‘Q7·Q9’에 신차용 타이어 공급", "category": "공급 / 계약", "date": "2026-05-20", "topics": ["타이어 설계 / 성능", "컴파운드 / 재료", "디지털 / AI"], "tags": ["고순도 실리카", "이중 카카스", "비드", "AI 컴파운드"], "summary": "아우디 SUV용 타이어의 실리카 배합, 이중 카카스와 비드 설계를 설명한다. 다른 적용 제품에서는 AI를 활용한 배합 최적화와 성능 간 균형을 소개한다.", "study": "공부 질문: 고무 배합과 골격 설계의 영향을 분리해 평가하고, AI 배합 후보를 실제 성능 시험으로 검증하는 절차를 생각해보자."}, {"id": "hankook-633223", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633223.html", "title": "한국타이어, ‘뉘르부르크링 24시’ HWA AG 차량에 레이싱 타이어 공급", "category": "공급 / 계약", "date": "2026-05-13", "topics": ["타이어 설계 / 성능"], "tags": ["HWA", "벤투스 F200", "뉘르부르크링 24시", "SP-X"], "summary": "뉘르부르크링 24시 HWA 차량에 벤투스 F200을 공급하는 기술 협력을 소개한다. 특수 클래스 차량의 접지·고속 안정성·조향 요구를 다룬다.", "study": "공부 질문: 양산 차량용 타이어와 내구 레이스용 타이어에서 개발 요구와 운용 지원 항목은 어떻게 달라질까?"}, {"id": "hankook-633198", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633198.html", "title": "한국타이어, 2026년 1분기 실적 발표", "category": "재무 / 사업전략", "date": "2026-05-08", "topics": [], "tags": ["2026년 1분기", "연결 실적", "타이어 부문", "매출 구성"], "summary": "2026년 1분기 연결 기준과 타이어 사업의 매출·이익을 나눠 발표했다. 고부가 제품 구성과 전동화 차량용 타이어 확대에 따른 사업 변화를 설명한다.", "study": "공부 질문: 연구개발·생산 투자와 제품 구성 변화가 실적에 반영되는 시차를 어떤 자료로 확인할 수 있을까?"}, {"id": "hankook-633132", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.633132.html", "title": "한국타이어, 인피니티 ‘올 뉴 QX65’에 신차용 타이어 공급", "category": "공급 / 계약", "date": "2026-04-23", "topics": ["타이어 설계 / 성능", "컴파운드 / 재료", "소음 / 진동"], "tags": ["다이나프로 HP2", "폴리에스터 카카스", "실리카", "저소음 패턴"], "summary": "인피니티 SUV용 다이나프로 HP2의 골격·배합·패턴 설계를 설명한다. 고강도 폴리에스터 카카스, 실리카 배합과 소음 저감 패턴이 주요 요소다.", "study": "공부 질문: 형상 안정성·회전저항·소음의 개선 효과를 구조·재료·패턴 각각의 설계 변수와 연결해보자."}, {"id": "hankook-632989", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.632989.html", "title": "한국타이어, 유럽 자동차 전문지 초고성능 타이어 테스트에서 압도적 성과", "category": "시험 / 성능검증", "date": "2026-03-31", "topics": ["타이어 설계 / 성능"], "tags": ["벤투스 에보", "핸들링", "제동", "접지"], "summary": "벤투스 에보의 전문지 비교 시험에서 마른·젖은 노면과 오프로드 성능을 평가한 결과를 소개한다. 여러 노면의 성능을 함께 살펴볼 자료다.", "study": "공부 질문: 시험마다 노면·규격·차량이 다를 때 결과를 단순 합산하지 않고 개발 목표와 비교하려면 무엇을 확인해야 할까?"}, {"id": "hankook-632979", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.632979.html", "title": "한국타이어, 대형 카고트럭∙트랙터 전륜용 타이어 ‘스마트플렉스 AH51+’ 신규 규격 출시", "category": "상용차 / 내구성", "date": "2026-03-30", "topics": ["타이어 설계 / 성능"], "tags": ["스마트플렉스 AH51+", "스파이럴코일", "히든그루브", "TWES"], "summary": "대형 카고·트랙터 전륜용 AH51+의 새 규격과 설계를 다룬다. 보강 구조, 마모 이후의 홈과 패턴 기술을 통해 수명·균일 마모·돌 끼임에 대응한다.", "study": "공부 질문: 마모가 진행된 뒤에도 필요한 성능을 유지하려면 초기 패턴과 잔여 패턴을 어떤 조건에서 평가해야 할까?"}, {"id": "hankook-632966", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.632966.html", "title": "한국타이어, 美 포드 최고 권위 품질상 ‘2025 QR 제로 어워드’ 수상", "category": "품질 / 생산관리", "date": "2026-03-26", "topics": ["공정 / 자원순환"], "tags": ["금산공장", "포드 QR 제로", "고객 품질", "생산체계"], "summary": "금산공장의 포드 품질상 수상 사례를 소개한다. 고객사가 요구하는 품질 수준과 생산 거점의 일관된 관리 체계를 연결해 볼 수 있다.", "study": "공부 질문: 고객 불량·공정 불량·출하 품질 지표를 구분하고, 재발 방지 활동의 효과를 어떤 지표로 추적할까?"}, {"id": "hankook-632944", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.632944.html", "title": "한국타이어, 기아(KIA) 소형 전기 SUV ‘EV2’에 신차용 타이어 공급", "category": "공급 / 계약", "date": "2026-03-24", "topics": ["전기차 / 저회전저항", "컴파운드 / 재료", "타이어 설계 / 성능"], "tags": ["아이온 에보", "아이온 GT", "아라미드", "지속가능 원료"], "summary": "기아 EV2 적용 타이어의 보강 벨트·형상 기술과 아이온 GT를 소개한다. 전기차의 회전저항·접지·마모 요구와 지속가능 소재 적용을 함께 다룬다.", "study": "공부 질문: 소재 변경과 경량·강성 설계를 동시에 진행할 때 각 변경의 효과를 분리해 검증하는 실험을 설계해보자."}, {"id": "hankook-632892", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.632892.html", "title": "한국타이어, 고속버스용 프리미엄 타이어 ‘스마트 투어링 AL31’ 국내 출시", "category": "상용차 / 내구성", "date": "2026-03-18", "topics": ["타이어 설계 / 성능"], "tags": ["스마트 투어링 AL31", "디커플링 그루브", "히든그루브", "TWES"], "summary": "중장거리 버스 전륜용 AL31의 홈·패턴 기술을 설명한다. 주행 안정성과 수명, 마모 상태를 고려하는 상용 타이어 설계 자료다.", "study": "공부 질문: 고속버스 전륜의 사용 조건을 화물차 구동축과 비교하고, 마모 균일성·조향 안정성을 평가할 항목을 정리해보자."}, {"id": "hankook-632886", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.632886.html", "title": "한국타이어, 헤이딜러와 고품질 인증 중고차 공급 체계 구축에 맞손", "category": "공급 / 계약", "date": "2026-03-17", "topics": ["품질 / 생산관리"], "tags": ["헤이딜러", "인증 중고차", "상품화 기준", "타이어 품질"], "summary": "헤이딜러와 타이어 공급 및 중고차 상품화 품질 기준을 고도화하는 협약이다. 차량 안전과 연결되는 타이어 상태를 품질 기준으로 관리하는 내용을 다룬다.", "study": "공부 질문: 중고차 상품화에서 교체·유지 판정을 내릴 검사 기준과 이력 추적 항목을 어떻게 설계할까?"}, {"id": "hankook-632865", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.632865.html", "title": "한국타이어, BMW 노이어 클라세 첫 SAV ‘더 뉴 iX3’에 신차용 타이어 공급", "category": "공급 / 계약", "date": "2026-03-16", "topics": ["전기차 / 저회전저항", "컴파운드 / 재료"], "tags": ["BMW iX3", "아이온 에보 SUV", "보강 벨트", "프로파일"], "summary": "BMW iX3용 아이온 에보 SUV 공급을 소개한다. 아라미드 보강과 배합·프로파일 설계를 통해 전기차의 강성·마모·전비 요구에 대응하는 내용을 담고 있다.", "study": "공부 질문: EV 타이어의 수명과 에너지 효율 개선을 입증할 때 하중·토크·시험 주행 조건을 어떻게 통제할까?"}, {"id": "hankook-632836", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.632836.html", "title": "한국타이어, 메르세데스-벤츠 ‘더 뉴 메르세데스-벤츠 S-클래스’에 신차용 타이어 공급", "category": "공급 / 계약", "date": "2026-03-12", "topics": ["타이어 설계 / 성능", "소음 / 진동", "컴파운드 / 재료"], "tags": ["벤투스 S1 에보3", "인터락킹", "인아웃 듀얼 피치", "아라미드"], "summary": "S-클래스용 타이어의 아라미드 보강·실리카 배합을 설명한다. 맞물림 형태의 홈과 안팎이 다른 피치 설계로 배수·접지·소음을 함께 고려한다.", "study": "공부 질문: 안팎 패턴을 달리할 때 접지 압력·배수·소음이 어떻게 달라질지 가설을 세우고 검증 방법을 정리해보자."}, {"id": "hankook-632804", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.632804.html", "title": "한국타이어, 포드 순수 전기 SUV ‘머스탱 마하-E’에 신차용 타이어 공급", "category": "공급 / 계약", "date": "2026-03-06", "topics": ["전기차 / 저회전저항", "컴파운드 / 재료", "품질 / 생산관리"], "tags": ["머스탱 마하-E", "아이온 에보", "EV 컴파운드", "포드 Q1"], "summary": "포드 전기 SUV용 타이어의 형상·보강 벨트·배합·홈 설계를 설명한다. 공급 사례와 함께 포드가 생산 거점에 부여하는 품질 인증도 소개한다.", "study": "공부 질문: 차종 전용 설계 승인과 생산 공장의 품질체계 승인을 구분하고 개발 이후 품질을 유지하는 방법을 정리해보자."}, {"id": "hankook-632749", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.632749.html", "title": "한국타이어 헝가리공장, 재생에너지 장기 전력구매계약(PPA) 체결", "category": "환경 / 에너지", "date": "2026-02-22", "topics": ["구매 / 공급망", "공정 / 자원순환", "공급 / 계약"], "tags": ["헝가리공장", "PPA", "재생에너지", "장기 조달"], "summary": "헝가리공장이 태양광 전력을 장기 계약으로 조달하는 사례다. 계약 기간·전력량과 공장 사용 전력의 대체 비중을 통해 에너지 전환을 설명한다.", "study": "공부 질문: 설비를 직접 설치하는 방식과 PPA를 이용하는 방식의 공급 안정성·가격·배출량 산정 조건을 어떻게 비교할까?"}, {"id": "hankook-632667", "url": "https://www.hankooktire.com/kr/ko/company/media-list/media-detail.632667.html", "title": "한국타이어, 2025년 매출액 21조 2,022억 원, 영업이익 1조 8,425억 원", "category": "재무 / 사업전략", "date": "2026-02-04", "topics": [], "tags": ["2025년 실적", "연결 범위", "타이어 부문", "제품 구성"], "summary":